BEGIN;
INSERT INTO permission_catalog(permission_code,domain,risk_class,sod_class) VALUES
 ('GROUP.CONSOLIDATION.CONFIG.VIEW','CONSOLIDATION','LOW','READ'),
 ('GROUP.CONSOLIDATION.CONFIG.CREATE','CONSOLIDATION','HIGH','CONSOLIDATION_CONFIG_DRAFT'),
 ('GROUP.CONSOLIDATION.CONFIG.SUBMIT','CONSOLIDATION','HIGH','CONSOLIDATION_CONFIG_SUBMIT'),
 ('GROUP.CONSOLIDATION.CONFIG.APPROVE','CONSOLIDATION','CRITICAL','CONSOLIDATION_CONFIG_APPROVE')
ON CONFLICT(permission_code) DO UPDATE SET active=true,domain=EXCLUDED.domain,risk_class=EXCLUDED.risk_class,sod_class=EXCLUDED.sod_class,version=permission_catalog.version+1,effective_to=NULL;
INSERT INTO runtime_human_permission_authority(permission_code,authority_class) VALUES
 ('GROUP.CONSOLIDATION.CONFIG.VIEW','READ'),('GROUP.CONSOLIDATION.CONFIG.CREATE','DRAFT'),('GROUP.CONSOLIDATION.CONFIG.SUBMIT','SUBMIT'),('GROUP.CONSOLIDATION.CONFIG.APPROVE','APPROVE')
ON CONFLICT(permission_code) DO UPDATE SET authority_class=EXCLUDED.authority_class;

CREATE TABLE consolidation_configuration_workflow(
 consolidation_configuration_workflow_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenant(tenant_id),reporting_entity_id uuid NOT NULL,reporting_period_id uuid NOT NULL,
 group_ref text NOT NULL CHECK(group_ref=btrim(group_ref) AND length(group_ref) BETWEEN 1 AND 160),currency char(3) NOT NULL CHECK(currency~'^[A-Z]{3}$'),
 version bigint NOT NULL CHECK(version>0),members jsonb NOT NULL CHECK(jsonb_typeof(members)='array'),account_maps jsonb NOT NULL CHECK(jsonb_typeof(account_maps)='array'),snapshot_hash text NOT NULL CHECK(snapshot_hash~'^sha256:[0-9a-f]{64}$'),
 status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','PENDING_APPROVAL','APPROVED')),revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),
 created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),submitted_by text,submitted_at timestamptz,approved_by text,approved_at timestamptz,consolidation_snapshot_id uuid,
 UNIQUE(tenant_id,reporting_entity_id,reporting_period_id,group_ref,version),UNIQUE(tenant_id,consolidation_configuration_workflow_id),
 FOREIGN KEY(tenant_id,reporting_entity_id,reporting_period_id) REFERENCES accounting_period(tenant_id,entity_id,period_id),
 FOREIGN KEY(consolidation_snapshot_id,tenant_id,reporting_entity_id,reporting_period_id) REFERENCES consolidation_snapshot(consolidation_snapshot_id,tenant_id,reporting_entity_id,reporting_period_id),
 CHECK(snapshot_hash=refs_jsonb_hash(jsonb_build_object('group_ref',group_ref,'currency',currency,'members',members,'account_maps',account_maps))),
 CHECK((submitted_by IS NULL)=(submitted_at IS NULL) AND (approved_by IS NULL)=(approved_at IS NULL)),
 CHECK(submitted_by IS NULL OR submitted_by<>created_by),CHECK(approved_by IS NULL OR approved_by<>created_by AND approved_by<>submitted_by),
 CHECK((status='DRAFT' AND revision=0 AND submitted_by IS NULL AND approved_by IS NULL AND consolidation_snapshot_id IS NULL)
    OR(status='PENDING_APPROVAL' AND revision=1 AND submitted_by IS NOT NULL AND approved_by IS NULL AND consolidation_snapshot_id IS NULL)
    OR(status='APPROVED' AND revision=2 AND submitted_by IS NOT NULL AND approved_by IS NOT NULL AND consolidation_snapshot_id IS NOT NULL))
);
CREATE TABLE consolidation_configuration_history(
 consolidation_configuration_history_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),consolidation_configuration_workflow_id uuid NOT NULL,tenant_id uuid NOT NULL,from_status text,to_status text NOT NULL,revision bigint NOT NULL,actor_id text NOT NULL,reason text NOT NULL,event_hash text NOT NULL CHECK(event_hash~'^sha256:[0-9a-f]{64}$'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(consolidation_configuration_workflow_id,revision),FOREIGN KEY(tenant_id,consolidation_configuration_workflow_id) REFERENCES consolidation_configuration_workflow(tenant_id,consolidation_configuration_workflow_id)
);
CREATE TABLE consolidation_configuration_gate(backend_pid integer NOT NULL,transaction_id bigint NOT NULL,tenant_id uuid NOT NULL,consolidation_configuration_workflow_id uuid NOT NULL,operation text NOT NULL CHECK(operation IN('PENDING_APPROVAL','APPROVED')),PRIMARY KEY(backend_pid,transaction_id,tenant_id,consolidation_configuration_workflow_id,operation));
ALTER TABLE consolidation_configuration_workflow ENABLE ROW LEVEL SECURITY;ALTER TABLE consolidation_configuration_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY consolidation_configuration_workflow_scope ON consolidation_configuration_workflow USING(tenant_id=refs_current_tenant() AND refs_entity_allowed(reporting_entity_id));
CREATE POLICY consolidation_configuration_history_scope ON consolidation_configuration_history USING(EXISTS(SELECT 1 FROM consolidation_configuration_workflow w WHERE w.tenant_id=refs_current_tenant() AND w.consolidation_configuration_workflow_id=consolidation_configuration_history.consolidation_configuration_workflow_id AND refs_entity_allowed(w.reporting_entity_id)));
REVOKE ALL ON consolidation_configuration_workflow,consolidation_configuration_history,consolidation_configuration_gate FROM PUBLIC,refs_app;
CREATE FUNCTION refs_guard_consolidation_configuration_workflow() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Consolidation configuration is retained evidence' USING ERRCODE='55000';END IF;
 IF NOT EXISTS(SELECT 1 FROM consolidation_configuration_gate g WHERE g.backend_pid=pg_backend_pid() AND g.transaction_id=txid_current() AND g.tenant_id=OLD.tenant_id AND g.consolidation_configuration_workflow_id=OLD.consolidation_configuration_workflow_id AND g.operation=NEW.status) OR NEW.revision<>OLD.revision+1 OR (to_jsonb(NEW)-ARRAY['status','revision','submitted_by','submitted_at','approved_by','approved_at','consolidation_snapshot_id']::text[]) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','submitted_by','submitted_at','approved_by','approved_at','consolidation_snapshot_id']::text[]) THEN RAISE EXCEPTION 'Consolidation configuration mutation requires an authoritative command' USING ERRCODE='42501';END IF;RETURN NEW;
END;$$;
CREATE TRIGGER consolidation_configuration_workflow_protect BEFORE UPDATE OR DELETE ON consolidation_configuration_workflow FOR EACH ROW EXECUTE FUNCTION refs_guard_consolidation_configuration_workflow();
CREATE TRIGGER consolidation_configuration_history_append_only BEFORE UPDATE OR DELETE ON consolidation_configuration_history FOR EACH ROW EXECUTE FUNCTION reject_mutation();

CREATE FUNCTION refs_consolidation_configuration_hash(p_tenant uuid,p_entity uuid,p_period uuid,p_group text,p_currency text,p_members jsonb,p_maps jsonb,p_reason text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ SELECT refs_jsonb_hash(jsonb_build_object('schema_version','CONSOLIDATION_CONFIGURATION_CREATE_V1','tenant_id',p_tenant,'entity_id',p_entity,'period_id',p_period,'group_ref',p_group,'currency',p_currency,'members',p_members,'account_maps',p_maps,'reason',p_reason)) $$;
CREATE FUNCTION refs_consolidation_configuration_transition_hash(p_tenant uuid,p_entity uuid,p_workflow uuid,p_action text,p_revision bigint,p_reason text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ SELECT refs_jsonb_hash(jsonb_build_object('schema_version','CONSOLIDATION_CONFIGURATION_TRANSITION_V1','tenant_id',p_tenant,'entity_id',p_entity,'workflow_id',p_workflow,'action',p_action,'revision',p_revision,'reason',p_reason)) $$;
CREATE FUNCTION refs_validate_consolidation_configuration(p_tenant uuid,p_entity uuid,p_period uuid,p_currency text,p_members jsonb,p_maps jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE period_row accounting_period;member jsonb;map jsonb;member_id uuid;member_period uuid;account_entity uuid;
BEGIN
 SELECT * INTO period_row FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=p_period FOR SHARE;
 IF NOT FOUND OR period_row.ledger_code<>'PRIMARY' OR period_row.status<>'OPEN' OR jsonb_array_length(p_members)<1 OR jsonb_array_length(p_members)>200 OR jsonb_array_length(p_maps)<1 OR jsonb_array_length(p_maps)>5000 THEN RAISE EXCEPTION 'Invalid consolidation configuration scope or population' USING ERRCODE='23514';END IF;
 FOR member IN SELECT value FROM jsonb_array_elements(p_members) LOOP
  IF ARRAY(SELECT jsonb_object_keys(member) ORDER BY 1)<>ARRAY['member_entity_id','member_period_id','member_receipt_hash','member_ref','member_snapshot_hash','member_source_ref','member_source_version'] OR member->>'member_entity_id'!~'^[0-9a-f-]{36}$' OR member->>'member_period_id'!~'^[0-9a-f-]{36}$' OR member->>'member_snapshot_hash'!~'^sha256:[0-9a-f]{64}$' OR member->>'member_receipt_hash'!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Malformed consolidation member' USING ERRCODE='23514';END IF;
  member_id:=(member->>'member_entity_id')::uuid;member_period:=(member->>'member_period_id')::uuid;PERFORM refs_assert_scope(p_tenant,member_id,'GL.REPORT.VIEW');
  IF NOT EXISTS(SELECT 1 FROM accounting_period p JOIN entity e ON e.tenant_id=p.tenant_id AND e.entity_id=p.entity_id WHERE p.tenant_id=p_tenant AND p.entity_id=member_id AND p.period_id=member_period AND p.ledger_code='PRIMARY' AND p.starts_on=period_row.starts_on AND p.ends_on=period_row.ends_on AND e.base_currency=p_currency FOR SHARE) THEN RAISE EXCEPTION 'Consolidation member is outside the reporting period or currency' USING ERRCODE='23514';END IF;
 END LOOP;
 IF (SELECT count(DISTINCT value->>'member_entity_id') FROM jsonb_array_elements(p_members))<>jsonb_array_length(p_members) THEN RAISE EXCEPTION 'Duplicate consolidation member' USING ERRCODE='23514';END IF;
 FOR map IN SELECT value FROM jsonb_array_elements(p_maps) LOOP
  IF ARRAY(SELECT jsonb_object_keys(map) ORDER BY 1)<>ARRAY['mapping_hash','member_entity_id','presentation_account_code','presentation_side','source_account_code'] OR map->>'member_entity_id'!~'^[0-9a-f-]{36}$' OR map->>'mapping_hash'!~'^sha256:[0-9a-f]{64}$' OR map->>'source_account_code'!~'^[0-9A-Za-z._-]{1,64}$' OR map->>'presentation_account_code'!~'^[0-9A-Za-z._-]{1,64}$' OR map->>'presentation_side' NOT IN('DEBIT','CREDIT') THEN RAISE EXCEPTION 'Malformed consolidation account map' USING ERRCODE='23514';END IF;
  account_entity:=(map->>'member_entity_id')::uuid;IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_members) m WHERE (m->>'member_entity_id')::uuid=account_entity) OR NOT EXISTS(SELECT 1 FROM account_master a WHERE a.tenant_id=p_tenant AND a.entity_id=account_entity AND a.account_code=map->>'source_account_code' AND a.active FOR SHARE) THEN RAISE EXCEPTION 'Consolidation map lacks an active scoped member account' USING ERRCODE='23514';END IF;
 END LOOP;
 IF (SELECT count(DISTINCT (value->>'member_entity_id',value->>'source_account_code')) FROM jsonb_array_elements(p_maps))<>jsonb_array_length(p_maps) THEN RAISE EXCEPTION 'Duplicate consolidation account map' USING ERRCODE='23514';END IF;
END;$$;CREATE FUNCTION refs_consolidation_configuration_payload(p_tenant uuid,p_entity uuid,p_workflow uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ DECLARE w consolidation_configuration_workflow; BEGIN PERFORM refs_assert_scope(p_tenant,p_entity,'GROUP.CONSOLIDATION.CONFIG.VIEW');SELECT * INTO w FROM consolidation_configuration_workflow WHERE tenant_id=p_tenant AND reporting_entity_id=p_entity AND consolidation_configuration_workflow_id=p_workflow;IF NOT FOUND THEN RAISE EXCEPTION 'Consolidation configuration was not found' USING ERRCODE='P0002';END IF;RETURN jsonb_build_object('schema_version','CONSOLIDATION_CONFIGURATION_V1','workflow_id',w.consolidation_configuration_workflow_id,'tenant_id',w.tenant_id,'reporting_entity_id',w.reporting_entity_id,'reporting_period_id',w.reporting_period_id,'group_ref',w.group_ref,'currency',w.currency,'version',w.version::text,'members',w.members,'account_maps',w.account_maps,'snapshot_hash',w.snapshot_hash,'status',w.status,'revision',w.revision::text,'consolidation_snapshot_id',w.consolidation_snapshot_id,'created_by',w.created_by,'created_at',w.created_at,'submitted_by',w.submitted_by,'submitted_at',w.submitted_at,'approved_by',w.approved_by,'approved_at',w.approved_at);END;$$;
CREATE FUNCTION refs_create_consolidation_configuration(p_tenant uuid,p_entity uuid,p_period uuid,p_group text,p_currency text,p_members jsonb,p_maps jsonb,p_reason text,p_idempotency_key text,p_request_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();idem idempotency_receipt;workflow uuid:=gen_random_uuid();v bigint;payload jsonb;result jsonb;
BEGIN
 IF actor IS NULL OR p_group IS NULL OR p_group<>btrim(p_group) OR length(p_group) NOT BETWEEN 1 AND 160 OR p_currency !~'^[A-Z]{3}$' OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 8 AND 2000 OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 OR p_request_hash IS DISTINCT FROM refs_consolidation_configuration_hash(p_tenant,p_entity,p_period,p_group,p_currency,p_members,p_maps,p_reason) THEN RAISE EXCEPTION 'Invalid consolidation configuration create command' USING ERRCODE='22023';END IF;
 PERFORM refs_assert_scope(p_tenant,p_entity,'GROUP.CONSOLIDATION.CONFIG.CREATE');PERFORM refs_assert_scope(p_tenant,p_entity,'GROUP.CONSOLIDATION.CONFIG.VIEW');
 INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'CONSOLIDATION_CONFIG_CREATE:'||p_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='CONSOLIDATION_CONFIG_CREATE:'||p_entity AND idempotency_key=p_idempotency_key FOR UPDATE;
 IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Consolidation configuration idempotency conflict' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 PERFORM refs_validate_consolidation_configuration(p_tenant,p_entity,p_period,p_currency,p_members,p_maps);PERFORM pg_advisory_xact_lock(hashtextextended('CONSOLIDATION_CONFIG:'||p_entity::text||':'||p_period::text||':'||p_group,0));SELECT GREATEST(COALESCE((SELECT max(version) FROM consolidation_configuration_workflow WHERE tenant_id=p_tenant AND reporting_entity_id=p_entity AND reporting_period_id=p_period AND group_ref=p_group),0),COALESCE((SELECT max(version) FROM consolidation_snapshot WHERE tenant_id=p_tenant AND reporting_entity_id=p_entity AND reporting_period_id=p_period AND group_ref=p_group),0))+1 INTO v;
 INSERT INTO consolidation_configuration_workflow(consolidation_configuration_workflow_id,tenant_id,reporting_entity_id,reporting_period_id,group_ref,currency,version,members,account_maps,snapshot_hash,created_by) VALUES(workflow,p_tenant,p_entity,p_period,p_group,p_currency,v,p_members,p_maps,refs_jsonb_hash(jsonb_build_object('group_ref',p_group,'currency',p_currency,'members',p_members,'account_maps',p_maps)),actor);
 payload:=jsonb_build_object('workflow_id',workflow,'status','DRAFT','revision','0','version',v::text,'snapshot_hash',(SELECT snapshot_hash FROM consolidation_configuration_workflow WHERE consolidation_configuration_workflow_id=workflow));INSERT INTO consolidation_configuration_history(consolidation_configuration_workflow_id,tenant_id,from_status,to_status,revision,actor_id,reason,event_hash) VALUES(workflow,p_tenant,NULL,'DRAFT',0,actor,btrim(p_reason),refs_jsonb_hash(payload));INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'CONSOLIDATION_CONFIG_DRAFT_CREATED','CONSOLIDATION_CONFIGURATION',workflow,'CREATE',actor,'USER','GROUP.CONSOLIDATION.CONFIG.CREATE',p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'CONSOLIDATION_CONFIGURATION',workflow,'CONSOLIDATION_CONFIG_DRAFT_CREATED',payload,refs_jsonb_hash(payload));
 result:=refs_consolidation_configuration_payload(p_tenant,p_entity,workflow)||jsonb_build_object('idempotent',false);UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=201,response_body=result,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN result;END;$$;
CREATE FUNCTION refs_transition_consolidation_configuration(p_tenant uuid,p_entity uuid,p_workflow uuid,p_action text,p_revision bigint,p_reason text,p_idempotency_key text,p_request_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();action text:=upper(p_action);idem idempotency_receipt;w consolidation_configuration_workflow;next_status text;snapshot uuid:=gen_random_uuid();payload jsonb;result jsonb;
BEGIN
 IF actor IS NULL OR action NOT IN('SUBMIT','APPROVE') OR p_revision IS NULL OR p_revision<0 OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 8 AND 2000 OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 OR p_request_hash IS DISTINCT FROM refs_consolidation_configuration_transition_hash(p_tenant,p_entity,p_workflow,action,p_revision,p_reason) THEN RAISE EXCEPTION 'Invalid consolidation configuration transition' USING ERRCODE='22023';END IF;
 PERFORM refs_assert_scope(p_tenant,p_entity,'GROUP.CONSOLIDATION.CONFIG.'||action);PERFORM refs_assert_scope(p_tenant,p_entity,'GROUP.CONSOLIDATION.CONFIG.VIEW');INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'CONSOLIDATION_CONFIG_'||action||':'||p_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='CONSOLIDATION_CONFIG_'||action||':'||p_entity AND idempotency_key=p_idempotency_key FOR UPDATE;IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Consolidation configuration idempotency conflict' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 SELECT * INTO w FROM consolidation_configuration_workflow WHERE tenant_id=p_tenant AND reporting_entity_id=p_entity AND consolidation_configuration_workflow_id=p_workflow FOR UPDATE;IF NOT FOUND OR w.revision<>p_revision OR(action='SUBMIT' AND w.status<>'DRAFT')OR(action='APPROVE' AND(w.status<>'PENDING_APPROVAL' OR actor IN(w.created_by,w.submitted_by))) THEN RAISE EXCEPTION 'Consolidation configuration revision conflict or separation of duties violation' USING ERRCODE='40001';END IF;PERFORM refs_validate_consolidation_configuration(p_tenant,p_entity,w.reporting_period_id,w.currency,w.members,w.account_maps);next_status:=CASE action WHEN 'SUBMIT' THEN 'PENDING_APPROVAL' ELSE 'APPROVED' END;IF action='APPROVE' THEN INSERT INTO consolidation_snapshot(consolidation_snapshot_id,tenant_id,reporting_entity_id,reporting_period_id,group_ref,version,currency,source_ref,source_version,receipt_hash,snapshot_hash,prepared_by,approved_by,approved_at) VALUES(snapshot,p_tenant,p_entity,w.reporting_period_id,w.group_ref,w.version,w.currency,'CONSOLIDATION_CONFIGURATION:'||w.consolidation_configuration_workflow_id,w.version::text,w.snapshot_hash,w.snapshot_hash,w.created_by,actor,clock_timestamp());INSERT INTO consolidation_member SELECT snapshot,p_tenant,p_entity,w.reporting_period_id,(v->>'member_entity_id')::uuid,(v->>'member_period_id')::uuid,v->>'member_ref',v->>'member_source_ref',v->>'member_source_version',v->>'member_receipt_hash',v->>'member_snapshot_hash' FROM jsonb_array_elements(w.members) v;INSERT INTO consolidation_account_map SELECT snapshot,(v->>'member_entity_id')::uuid,v->>'source_account_code',v->>'presentation_account_code',v->>'presentation_side',v->>'mapping_hash' FROM jsonb_array_elements(w.account_maps) v;END IF;
 INSERT INTO consolidation_configuration_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_workflow,next_status);UPDATE consolidation_configuration_workflow SET status=next_status,revision=revision+1,submitted_by=CASE WHEN action='SUBMIT' THEN actor ELSE submitted_by END,submitted_at=CASE WHEN action='SUBMIT' THEN clock_timestamp() ELSE submitted_at END,approved_by=CASE WHEN action='APPROVE' THEN actor ELSE approved_by END,approved_at=CASE WHEN action='APPROVE' THEN clock_timestamp() ELSE approved_at END,consolidation_snapshot_id=CASE WHEN action='APPROVE' THEN snapshot ELSE consolidation_snapshot_id END WHERE consolidation_configuration_workflow_id=p_workflow;DELETE FROM consolidation_configuration_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=p_tenant AND consolidation_configuration_workflow_id=p_workflow AND operation=next_status;payload:=jsonb_build_object('workflow_id',p_workflow,'status',next_status,'revision',(w.revision+1)::text,'consolidation_snapshot_id',CASE WHEN action='APPROVE' THEN snapshot END);INSERT INTO consolidation_configuration_history(consolidation_configuration_workflow_id,tenant_id,from_status,to_status,revision,actor_id,reason,event_hash) VALUES(p_workflow,p_tenant,w.status,next_status,w.revision+1,actor,btrim(p_reason),refs_jsonb_hash(payload));INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'CONSOLIDATION_CONFIG_'||action,'CONSOLIDATION_CONFIGURATION',p_workflow,action,actor,'USER','GROUP.CONSOLIDATION.CONFIG.'||action,p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'CONSOLIDATION_CONFIGURATION',p_workflow,'CONSOLIDATION_CONFIG_'||action,payload,refs_jsonb_hash(payload));result:=refs_consolidation_configuration_payload(p_tenant,p_entity,p_workflow)||jsonb_build_object('idempotent',false);UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=200,response_body=result,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN result;END;$$;
CREATE FUNCTION refs_read_consolidation_configuration(p_tenant uuid,p_entity uuid,p_workflow uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ SELECT refs_consolidation_configuration_payload(p_tenant,p_entity,p_workflow) $$;
REVOKE ALL ON FUNCTION refs_consolidation_configuration_hash(uuid,uuid,uuid,text,text,jsonb,jsonb,text),refs_consolidation_configuration_transition_hash(uuid,uuid,uuid,text,bigint,text),refs_read_consolidation_configuration(uuid,uuid,uuid),refs_create_consolidation_configuration(uuid,uuid,uuid,text,text,jsonb,jsonb,text,text,text),refs_transition_consolidation_configuration(uuid,uuid,uuid,text,bigint,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION refs_consolidation_configuration_hash(uuid,uuid,uuid,text,text,jsonb,jsonb,text),refs_consolidation_configuration_transition_hash(uuid,uuid,uuid,text,bigint,text),refs_read_consolidation_configuration(uuid,uuid,uuid),refs_create_consolidation_configuration(uuid,uuid,uuid,text,text,jsonb,jsonb,text,text,text),refs_transition_consolidation_configuration(uuid,uuid,uuid,text,bigint,text,text,text) TO refs_app;
COMMIT;
